// MT2009_PLUS_COMBO_SAVE_V1 (decl) (server-patches/combosave, Autor: Mur4s): Kombinacja przezywa teleport/zmiane CH - stan w special flagu "combo.on".
void RestoreComboFromFlag(bool bEnterGame = false);

// MT2009_PLUS_COMBO_SAVE_V1 (restore) (server-patches/combosave, Autor: Mur4s): wolane z OnSetSpecialFlag (flagi z DB) i z
// Entergame - flagi moga przyjsc przed albo po wejsciu do gry, wiec "combo" wysylamy tylko w PHASE_GAME.
void CHARACTER::RestoreComboFromFlag(bool bEnterGame)
{
	if (!IsPC())
		return;

	BYTE idx = GetSpecialFlag("combo.on") > 0 ? (BYTE)GetSkillLevel(SKILL_COMBO) : 0;
	// Bez powtorki przy zwyklym przelaczeniu (UseSkill sam wysyla "combo");
	// w Entergame wysylamy zawsze, bo klient po teleporcie ma combo wylaczone.
	if (idx == 0 || (idx == m_bComboIndex && !bEnterGame))
		return;

	m_bComboIndex = idx;

	if (GetDesc() && GetDesc()->IsPhase(PHASE_GAME))
	{
		ChatPacket(CHAT_TYPE_COMMAND, "combo %d", m_bComboIndex);
		sys_log(0, "COMBO_RESTORE: %s idx %d", GetName(), m_bComboIndex);
	}
}

